INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$7b419faf$SATQ$, $SATQ$2a5f93a6-815c-478e-80c5-6726b61179d8$SATQ$::uuid, $SATQ$e8a33738-7bac-478f-8a3a-04c735d47cec$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1903, environmentalist John Muir guided President Theodore Roosevelt on a scenic, sprawling trip through California&rsquo;s Yosemite Valley. Upon returning from the three-day excursion, Roosevelt <span aria-hidden="true">______</span><span class="sr-only">blank</span> to conserve the nation&rsquo;s wilderness areas, a vow he upheld for his remaining six years in office.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"4deb279d-6b84-429a-9ec2-b8632c0d0a9c","content":"<p>is vowing</p>"},{"id":"0b3c4eee-e40f-4e87-8c6c-4d2f571ff0de","content":"<p>vowed</p>"},{"id":"bc8c5401-d0bc-406f-9dec-173c63457ad1","content":"<p>will vow</p>"},{"id":"57514955-024b-4f63-a100-9a3306537d83","content":"<p>vows</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["0b3c4eee-e40f-4e87-8c6c-4d2f571ff0de"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb &ldquo;vowed&rdquo; is consistent with the other past tense verbs (&ldquo;guided&rdquo; and &ldquo;upheld&rdquo;) used to narrate the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. </p><p>Choice A is incorrect because the present progressive tense verb &ldquo;is vowing&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. Choice C is incorrect because the future tense verb &ldquo;will vow&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. Choice D is incorrect because the simple present tense verb &ldquo;vows&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. </p>$SATQ$, false, 0, $SATQ$OSP-763-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$36f019e7-4547-402c-8cd2-5b09675cd1ed$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7b419faf","external_id":"2a5f93a6-815c-478e-80c5-6726b61179d8","vaultid":"e8a33738-7bac-478f-8a3a-04c735d47cec","uId":"18bf57ef-ad32-4fc4-a3be-981cf7565f4b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1903, environmentalist John Muir guided President Theodore Roosevelt on a scenic, sprawling trip through California&rsquo;s Yosemite Valley. Upon returning from the three-day excursion, Roosevelt <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to conserve the nation&rsquo;s wilderness areas, a vow he upheld for his remaining six years in office.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"4deb279d-6b84-429a-9ec2-b8632c0d0a9c","content":"<p>is vowing</p>"},{"id":"0b3c4eee-e40f-4e87-8c6c-4d2f571ff0de","content":"<p>vowed</p>"},{"id":"bc8c5401-d0bc-406f-9dec-173c63457ad1","content":"<p>will vow</p>"},{"id":"57514955-024b-4f63-a100-9a3306537d83","content":"<p>vows</p>"}],"keys":["0b3c4eee-e40f-4e87-8c6c-4d2f571ff0de"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb &ldquo;vowed&rdquo; is consistent with the other past tense verbs (&ldquo;guided&rdquo; and &ldquo;upheld&rdquo;) used to narrate the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. </p><p>Choice A is incorrect because the present progressive tense verb &ldquo;is vowing&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. Choice C is incorrect because the future tense verb &ldquo;will vow&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. Choice D is incorrect because the simple present tense verb &ldquo;vows&rdquo; isn&rsquo;t consistent with the past tense verbs used to narrate&nbsp;the events surrounding President Roosevelt&rsquo;s decision to conserve the nation&rsquo;s wilderness areas. </p>","parenttemplatename":"OSP-763-SEC","parenttemplateid":"","templateclusterid":"36f019e7-4547-402c-8cd2-5b09675cd1ed","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$7b950fc2$SATQ$, $SATQ$0b5a29de-5bdc-4eaa-8cd2-44e0da501b87$SATQ$::uuid, $SATQ$188dda45-f5e7-4004-ba20-0c99f1e4b090$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 2000, Nora de Hoyos Comstock, herself an owner of a successful consulting firm, sought to increase Latina representation in corporate <span aria-hidden="true">______</span><span class="sr-only">blank</span> founded<em> </em>Las Comadres para las Americas, an international community that for over two decades has served as a resource and information network for Latina business professionals.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d181d36e-5636-4826-b08a-58bf3d12e99e","content":"<p>settings she</p>"},{"id":"73d5a43a-272c-4fc0-b458-08e58071870c","content":"<p>settings, she</p>"},{"id":"db33d488-27b2-4c75-8af0-3af0129d9e95","content":"<p>settings and she</p>"},{"id":"4217767c-07d4-47c7-acc8-21de5037a19a","content":"<p>settings. She</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["4217767c-07d4-47c7-acc8-21de5037a19a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. It appropriately uses a period to mark the end of one independent clause ("In 2000&hellip;settings") and the start of another ("She founded&hellip;professionals").</p><p>Choice A is incorrect. This choice results in a run-on sentence error. Both the clause before the blank ("In 2000&hellip;settings") and the clause after the blank ("she&hellip;professionals") are independent clauses, so they need to be separated by punctuation. Choice B is incorrect. This choice results in a comma splice error. It incorrectly joins two independent clauses with just a comma. Linking two independent clauses with a comma also requires the use of a coordinating conjunction (like<em> for</em>, <em>and</em>, <em>nor</em>, <em>but</em>, <em>or</em>, <em>yet</em>, or <em>so</em>). Choice C is incorrect. This choice results in a run-on sentence, an error caused when two independent clauses are joined without punctuation or appropriate conjunctions. Since both the clause before the blank ("In 2000&hellip;settings") and the clause after the blank ("she&hellip;professionals") are independent, a comma would be required in addition to the coordinating conjunction "and."</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-E006$SATQ$, $SATQ$$SATQ$, $SATQ$3f11de3d-49e5-4122-b26b-3599e04b88f8$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7b950fc2","external_id":"0b5a29de-5bdc-4eaa-8cd2-44e0da501b87","vaultid":"188dda45-f5e7-4004-ba20-0c99f1e4b090","uId":"9b709fdc-1194-45f2-a835-81560d00c62b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 2000, Nora de Hoyos Comstock, herself an owner of a successful consulting firm, sought to increase Latina representation in corporate <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> founded<em> </em>Las Comadres para las Americas, an international community that for over two decades has served as a resource and information network for Latina business professionals.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d181d36e-5636-4826-b08a-58bf3d12e99e","content":"<p>settings she</p>"},{"id":"73d5a43a-272c-4fc0-b458-08e58071870c","content":"<p>settings, she</p>"},{"id":"db33d488-27b2-4c75-8af0-3af0129d9e95","content":"<p>settings and she</p>"},{"id":"4217767c-07d4-47c7-acc8-21de5037a19a","content":"<p>settings. She</p>"}],"keys":["4217767c-07d4-47c7-acc8-21de5037a19a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. It appropriately uses a period to mark the end of one independent clause (\"In 2000&hellip;settings\") and the start of another (\"She founded&hellip;professionals\").</p><p>Choice A is incorrect. This choice results in a run-on sentence error. Both the clause before the blank (\"In 2000&hellip;settings\") and the clause after the blank (\"she&hellip;professionals\") are independent clauses, so they need to be separated by punctuation. Choice B is incorrect. This choice results in a comma splice error. It incorrectly joins two independent clauses with just a comma. Linking two independent clauses with a comma also requires the use of a coordinating conjunction (like<em> for</em>, <em>and</em>, <em>nor</em>, <em>but</em>, <em>or</em>, <em>yet</em>, or <em>so</em>). Choice C is incorrect. This choice results in a run-on sentence, an error caused when two independent clauses are joined without punctuation or appropriate conjunctions. Since both the clause before the blank (\"In 2000&hellip;settings\") and the clause after the blank (\"she&hellip;professionals\") are independent, a comma would be required in addition to the coordinating conjunction \"and.\"</p>","parenttemplatename":"OSP-KA-BOU-E006","parenttemplateid":"","templateclusterid":"3f11de3d-49e5-4122-b26b-3599e04b88f8","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$7c48a6dd$SATQ$, $SATQ$69d8b8e6-123a-473c-bf90-991f3f3ba3d7$SATQ$::uuid, $SATQ$dcdfa31e-d978-41ff-b729-5042081614bc$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In the late 1960s, inspired in part by the sight of laundry hanging on a clothesline, African American abstract painter Sam Gilliam began to create his iconic &ldquo;Drape&rdquo; paintings. He applied bold, saturated hues to large canvases and <span aria-hidden="true">______</span><span class="sr-only">blank</span> them from ceilings or walls, causing the drooping fabric to cascade in dramatic loops and curves.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"54f3cac8-5c5e-4f0c-8644-f516b02e31f2","content":"<p>to have suspended</p>"},{"id":"d5c2b4d6-0408-40b4-9a13-0e5c695ec0aa","content":"<p>suspending</p>"},{"id":"ebbaf624-9ce6-4889-a83f-b77fa4342d27","content":"<p>to suspend</p>"},{"id":"3e21ab7a-adfc-4c33-b99e-b16d01e9146f","content":"<p>suspended</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["3e21ab7a-adfc-4c33-b99e-b16d01e9146f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The past tense of "suspended" matches the past tense of "applied," which has the same subject ("he") and takes place in the same context: "He applied&hellip;and [he] suspended."</p><p>Choice A is incorrect. The perfect infinitive "to have suspended" doesn&rsquo;t match the past tense of "applied," and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses. Choice B is incorrect. The present participle "suspending" doesn&rsquo;t match the past tense of "applied," and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses. Choice C is incorrect. The infinitive "to suspend" doesn&rsquo;t match the past tense of "applied," and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses.</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-E006$SATQ$, $SATQ$$SATQ$, $SATQ$338353b7-c5a8-47dc-b601-3bc148714cc1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7c48a6dd","external_id":"69d8b8e6-123a-473c-bf90-991f3f3ba3d7","vaultid":"dcdfa31e-d978-41ff-b729-5042081614bc","uId":"92474b5d-8aab-4bbe-a913-28f24a15b08f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In the late 1960s, inspired in part by the sight of laundry hanging on a clothesline, African American abstract painter Sam Gilliam began to create his iconic &ldquo;Drape&rdquo; paintings. He applied bold, saturated hues to large canvases and <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> them from ceilings or walls, causing the drooping fabric to cascade in dramatic loops and curves.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"54f3cac8-5c5e-4f0c-8644-f516b02e31f2","content":"<p>to have suspended</p>"},{"id":"d5c2b4d6-0408-40b4-9a13-0e5c695ec0aa","content":"<p>suspending</p>"},{"id":"ebbaf624-9ce6-4889-a83f-b77fa4342d27","content":"<p>to suspend</p>"},{"id":"3e21ab7a-adfc-4c33-b99e-b16d01e9146f","content":"<p>suspended</p>"}],"keys":["3e21ab7a-adfc-4c33-b99e-b16d01e9146f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The past tense of \"suspended\" matches the past tense of \"applied,\" which has the same subject (\"he\") and takes place in the same context: \"He applied&hellip;and [he] suspended.\"</p><p>Choice A is incorrect. The perfect infinitive \"to have suspended\" doesn&rsquo;t match the past tense of \"applied,\" and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses. Choice B is incorrect. The present participle \"suspending\" doesn&rsquo;t match the past tense of \"applied,\" and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses. Choice C is incorrect. The infinitive \"to suspend\" doesn&rsquo;t match the past tense of \"applied,\" and it can&rsquo;t serve as a verb on its own. These are both verbs with the same subject and in the same context, so there&rsquo;s no need to shift tenses.</p>","parenttemplatename":"OSP-KA-FSS-E006","parenttemplateid":"","templateclusterid":"338353b7-c5a8-47dc-b601-3bc148714cc1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$7c766ceb$SATQ$, $SATQ$b7676098-167d-4382-a6fa-0433eb35a466$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>A popular suite of mapping and spatial analysis software, ArcGIS enables cartographers like Karachi Cartography founder Namra Khalid <span aria-hidden="true">______</span><span class="sr-only">blank</span> maps by analyzing and arranging raw geospatial data.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1f97087d-f13a-477f-a82b-de6e0d6c7400","content":"<p>create</p>"},{"id":"22868f3e-8092-49c6-a1b3-d73f9b60731e","content":"<p>to create</p>"},{"id":"c5ce15f9-d576-4cfe-84b0-2c698dfcbb18","content":"<p>creating</p>"},{"id":"11efdfce-c28d-47c4-9d90-ca56937c87ac","content":"<p>created</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["22868f3e-8092-49c6-a1b3-d73f9b60731e"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb &ldquo;to create&rdquo; is correctly used to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps (by analyzing and arranging certain data).</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The finite verb &ldquo;create&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite participle &ldquo;creating&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb &ldquo;created&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"7c766ceb","external_id":"b7676098-167d-4382-a6fa-0433eb35a466","vaultid":null,"uId":"d5e0b0ed-1a96-4889-a068-83beffdebe57","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>A popular suite of mapping and spatial analysis software, ArcGIS enables cartographers like Karachi Cartography founder Namra Khalid <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> maps by analyzing and arranging raw geospatial data.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1f97087d-f13a-477f-a82b-de6e0d6c7400","content":"<p>create</p>"},{"id":"22868f3e-8092-49c6-a1b3-d73f9b60731e","content":"<p>to create</p>"},{"id":"c5ce15f9-d576-4cfe-84b0-2c698dfcbb18","content":"<p>creating</p>"},{"id":"11efdfce-c28d-47c4-9d90-ca56937c87ac","content":"<p>created</p>"}],"keys":["22868f3e-8092-49c6-a1b3-d73f9b60731e"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb &ldquo;to create&rdquo; is correctly used to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps (by analyzing and arranging certain data).</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The finite verb &ldquo;create&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite participle &ldquo;creating&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb &ldquo;created&rdquo; can&rsquo;t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$7ce4ee13$SATQ$, $SATQ$12d17397-3221-4a0e-8894-52e43b3a51af$SATQ$::uuid, $SATQ$36954c8d-25da-4db9-9713-5fba4536d8cd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>After immigrating from Mexico and obtaining U.S. citizenship, Octaviano Ambrosio Larrazolo entered politics, earning a reputation for being a fervent defender of Hispanic civil rights. In 1919 Larrazolo was elected governor of <span aria-hidden="true">______</span><span class="sr-only">blank</span> in 1928 he became the nation&rsquo;s first Hispanic U.S. Senator.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"3ade7f6f-b374-4489-be01-d16a3ffcb925","content":"<p>New Mexico and</p>"},{"id":"89cdbd81-d187-44d1-af13-43178938592a","content":"<p>New Mexico,</p>"},{"id":"a0f1861b-e8e7-4e80-a4cc-ce540cea8f35","content":"<p>New Mexico, and</p>"},{"id":"f54ccecf-03ac-4f94-9f14-4843eead3404","content":"<p>New Mexico</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a0f1861b-e8e7-4e80-a4cc-ce540cea8f35"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction "and" to join the first main clause ("In 1919 Larrazolo was elected governor of New Mexico") and the second main clause ("in 1928 he became the nation&rsquo;s first Hispanic US Senator").</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, $SATQ$OSP-779-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$7b538a9d-7c03-4932-802a-cb871f21a8bf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7ce4ee13","external_id":"12d17397-3221-4a0e-8894-52e43b3a51af","vaultid":"36954c8d-25da-4db9-9713-5fba4536d8cd","uId":"c8e54a37-8ca8-48a7-b8a0-eb89aaba577c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>After immigrating from Mexico and obtaining U.S. citizenship, Octaviano Ambrosio Larrazolo entered politics, earning a reputation for being a fervent defender of Hispanic civil rights. In 1919 Larrazolo was elected governor of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in 1928 he became the nation&rsquo;s first Hispanic U.S. Senator.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"3ade7f6f-b374-4489-be01-d16a3ffcb925","content":"<p>New Mexico and</p>"},{"id":"89cdbd81-d187-44d1-af13-43178938592a","content":"<p>New Mexico,</p>"},{"id":"a0f1861b-e8e7-4e80-a4cc-ce540cea8f35","content":"<p>New Mexico, and</p>"},{"id":"f54ccecf-03ac-4f94-9f14-4843eead3404","content":"<p>New Mexico</p>"}],"keys":["a0f1861b-e8e7-4e80-a4cc-ce540cea8f35"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction \"and\" to join the first main clause (\"In 1919 Larrazolo was elected governor of New Mexico\") and the second main clause (\"in 1928 he became the nation&rsquo;s first Hispanic US Senator\").</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>","parenttemplatename":"OSP-779-SEC","parenttemplateid":"","templateclusterid":"7b538a9d-7c03-4932-802a-cb871f21a8bf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$7e37affc$SATQ$, $SATQ$b20a8ed2-86bb-455d-a1a5-7bdec6418766$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>That the geographic center of North America lay in the state of North Dakota was conceded by all <span aria-hidden="true">______</span><span class="sr-only">blank</span> establishing its precise coordinates proved more divisive.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"f7611c35-f081-4e3c-8b8b-692e4c2bf2c1","content":"<p>involved<span data-ssml-say-as=\"characters\">:</span></p>"},{"id":"7ea461a8-6aca-45f5-8910-9ceb22e816d2","content":"<p>involved<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"d2324ad5-cb70-415b-9b07-ba2edc249453","content":"<p>involved</p>"},{"id":"9db825c3-fe2d-4b91-b554-6de1464c124f","content":"<p>involved<span data-ssml-say-as=\"characters\">;</span></p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["9db825c3-fe2d-4b91-b554-6de1464c124f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause ("That the...involved") and the second main clause ("establishing...divisive"). Further, the semicolon is the most appropriate choice when joining two separate, parallel statements, such as here, where the information following the semicolon contrasts with the information before.</p><p>Choice A is incorrect because placing a colon after "involved" illogically indicates that the information in the second main clause (the precise location was the subject of disagreement) explains or amplifies the information in the previous main clause (the general location was agreed upon by all). Instead, the information in the second clause contrasts with the previous information. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"7e37affc","external_id":"b20a8ed2-86bb-455d-a1a5-7bdec6418766","vaultid":null,"uId":"b07618e0-10f0-41a4-bea2-3ac36aebcaa6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>That the geographic center of North America lay in the state of North Dakota was conceded by all <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> establishing its precise coordinates proved more divisive.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"f7611c35-f081-4e3c-8b8b-692e4c2bf2c1","content":"<p>involved<span data-ssml-say-as=\"characters\">:</span></p>"},{"id":"7ea461a8-6aca-45f5-8910-9ceb22e816d2","content":"<p>involved<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"d2324ad5-cb70-415b-9b07-ba2edc249453","content":"<p>involved</p>"},{"id":"9db825c3-fe2d-4b91-b554-6de1464c124f","content":"<p>involved<span data-ssml-say-as=\"characters\">;</span></p>"}],"keys":["9db825c3-fe2d-4b91-b554-6de1464c124f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (\"That the...involved\") and the second main clause (\"establishing...divisive\"). Further, the semicolon is the most appropriate choice when joining two separate, parallel statements, such as here, where the information following the semicolon contrasts with the information before.</p><p>Choice A is incorrect because placing a colon after \"involved\" illogically indicates that the information in the second main clause (the precise location was the subject of disagreement) explains or amplifies the information in the previous main clause (the general location was agreed upon by all). Instead, the information in the second clause contrasts with the previous information. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$7f1df833$SATQ$, $SATQ$96889af3-0842-483d-ae93-cd1be0cf6ade$SATQ$::uuid, $SATQ$4fb0fb45-98bd-4a16-8045-aca619cb1f46$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In 1966, Emmett Ashford became the first African American to umpire a Major League Baseball game. His energetic gestures announcing when a player had struck out and his habit of barreling after a hit ball to see if it would land out of <span aria-hidden="true">______</span><span class="sr-only">blank</span> transform the traditionally solemn umpire role into a dynamic one.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d8447fe7-35c8-4cb9-9f49-8d508c8f9552","content":"<p>bounds helped</p>"},{"id":"9fdc9885-44f0-475f-8ffc-ca3696206659","content":"<p>bounds, helping</p>"},{"id":"c39af0a0-5cd4-4d3d-a101-d670fb0c78c9","content":"<p>bounds that helped</p>"},{"id":"bca9ea66-86b9-4e20-b311-e725ee60bffc","content":"<p>bounds to help</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["d8447fe7-35c8-4cb9-9f49-8d508c8f9552"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is finite verb use in a main clause. A main clause requires a finite verb to perform the action of the subject (in this case, Ashford&rsquo;s &ldquo;gestures&rdquo; and &ldquo;habit&rdquo;), and this choice supplies the finite past tense verb &ldquo;helped&rdquo; to indicate what Ashford&rsquo;s gestures and habit helped accomplish. </p><p>Choice B is incorrect because the non-finite participle &ldquo;helping&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the relative clause &ldquo;that helped&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the non-finite to-infinitive &ldquo;to help&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-630-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$8e5a15a1-3a30-442a-872a-48484c932cbf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7f1df833","external_id":"96889af3-0842-483d-ae93-cd1be0cf6ade","vaultid":"4fb0fb45-98bd-4a16-8045-aca619cb1f46","uId":"586ff067-ac54-4e99-b2c5-2fd02887ec1d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In 1966, Emmett Ashford became the first African American to umpire a Major League Baseball game. His energetic gestures announcing when a player had struck out and his habit of barreling after a hit ball to see if it would land out of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> transform the traditionally solemn umpire role into a dynamic one.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d8447fe7-35c8-4cb9-9f49-8d508c8f9552","content":"<p>bounds helped</p>"},{"id":"9fdc9885-44f0-475f-8ffc-ca3696206659","content":"<p>bounds, helping</p>"},{"id":"c39af0a0-5cd4-4d3d-a101-d670fb0c78c9","content":"<p>bounds that helped</p>"},{"id":"bca9ea66-86b9-4e20-b311-e725ee60bffc","content":"<p>bounds to help</p>"}],"keys":["d8447fe7-35c8-4cb9-9f49-8d508c8f9552"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is finite verb use in a main clause. A main clause requires a finite verb to perform the action of the subject (in this case, Ashford&rsquo;s &ldquo;gestures&rdquo; and &ldquo;habit&rdquo;), and this choice supplies the finite past tense verb &ldquo;helped&rdquo; to indicate what Ashford&rsquo;s gestures and habit helped accomplish. </p><p>Choice B is incorrect because the non-finite participle &ldquo;helping&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the relative clause &ldquo;that helped&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the non-finite to-infinitive &ldquo;to help&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>","parenttemplatename":"OSP-630-SEC","parenttemplateid":"","templateclusterid":"8e5a15a1-3a30-442a-872a-48484c932cbf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$7f226b4b$SATQ$, $SATQ$a1555b5a-e2c7-4111-820a-85ed1923e629$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In a 2023 study, researchers documented a fascinating behavior in the aquatic plant <em>Elodea densa</em>. When exposed to low levels of light, the plant&rsquo;s <span aria-hidden="true">______</span><span class="sr-only">blank</span> the cellular organs that generate energy from light&mdash;reshuffled to form a tightly packed, glass-like surface ideal for collecting more light.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"02e49181-b91c-4478-91a8-07dc90e5f725","content":"<p>chloroplasts</p>"},{"id":"dc7c4c9c-b9ca-44b2-989a-444468ef6269","content":"<p>chloroplasts;</p>"},{"id":"8fc494a0-d581-4e35-8c28-4e24f7230818","content":"<p>chloroplasts,</p>"},{"id":"e1110fed-2920-4228-8e6b-66ac1895b270","content":"<p>chloroplasts&mdash;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["e1110fed-2920-4228-8e6b-66ac1895b270"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The dash after "chloroplasts" pairs with the dash after "from light" to separate the supplementary element "the cellular organs that generate energy from light" from the rest of the sentence. This supplementary element functions to define the term "chloroplasts," and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a semicolon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"7f226b4b","external_id":"a1555b5a-e2c7-4111-820a-85ed1923e629","vaultid":null,"uId":"05e74510-357d-40bd-b98c-f5e9475c510f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In a 2023 study, researchers documented a fascinating behavior in the aquatic plant <em>Elodea densa</em>. When exposed to low levels of light, the plant&rsquo;s <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the cellular organs that generate energy from light&mdash;reshuffled to form a tightly packed, glass-like surface ideal for collecting more light.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"02e49181-b91c-4478-91a8-07dc90e5f725","content":"<p>chloroplasts</p>"},{"id":"dc7c4c9c-b9ca-44b2-989a-444468ef6269","content":"<p>chloroplasts;</p>"},{"id":"8fc494a0-d581-4e35-8c28-4e24f7230818","content":"<p>chloroplasts,</p>"},{"id":"e1110fed-2920-4228-8e6b-66ac1895b270","content":"<p>chloroplasts&mdash;</p>"}],"keys":["e1110fed-2920-4228-8e6b-66ac1895b270"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The dash after \"chloroplasts\" pairs with the dash after \"from light\" to separate the supplementary element \"the cellular organs that generate energy from light\" from the rest of the sentence. This supplementary element functions to define the term \"chloroplasts,\" and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a semicolon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$7f48b098$SATQ$, $SATQ$98341ec4-6938-453c-9ee4-11a09b55eabf$SATQ$::uuid, $SATQ$0e40c9fe-c8f6-48eb-b840-a3fcde7a7df1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Photosynthesis, the mechanism by which plants use sunlight to turn carbon dioxide and water into <span aria-hidden="true">______</span><span class="sr-only">blank</span> is fueled in part by an enzyme called Photosystem II that harvests energy-giving electrons from water molecules.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"6ea4f2eb-af46-4f29-8448-0e5b5f2c0236","content":"<p>nutrients</p>"},{"id":"3df07580-86b7-4468-9352-389416670d28","content":"<p>nutrients and</p>"},{"id":"1a23d05a-8e1a-4483-8ed1-77cd5d62bd22","content":"<p>nutrients,</p>"},{"id":"a01770f3-e5cc-438a-b05c-6bc967045e53","content":"<p>nutrients&mdash;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1a23d05a-8e1a-4483-8ed1-77cd5d62bd22"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;nutrients&rdquo; pairs with the comma after &ldquo;photosynthesis&rdquo; to separate the supplementary element &ldquo;the mechanism by which plants use sunlight to turn carbon dioxide and water into nutrients&rdquo; from the rest of the sentence. This supplementary element functions to define the term &ldquo;photosynthesis,&rdquo; and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a conjunction can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a dash can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. </p>$SATQ$, false, 0, $SATQ$OSP-724-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$8182d867-dbdd-4c19-9cef-b91abef36e2b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"7f48b098","external_id":"98341ec4-6938-453c-9ee4-11a09b55eabf","vaultid":"0e40c9fe-c8f6-48eb-b840-a3fcde7a7df1","uId":"12f24da0-bb74-44de-abc2-6f62ec4c8549","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Photosynthesis, the mechanism by which plants use sunlight to turn carbon dioxide and water into <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> is fueled in part by an enzyme called Photosystem II that harvests energy-giving electrons from water molecules.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"6ea4f2eb-af46-4f29-8448-0e5b5f2c0236","content":"<p>nutrients</p>"},{"id":"3df07580-86b7-4468-9352-389416670d28","content":"<p>nutrients and</p>"},{"id":"1a23d05a-8e1a-4483-8ed1-77cd5d62bd22","content":"<p>nutrients,</p>"},{"id":"a01770f3-e5cc-438a-b05c-6bc967045e53","content":"<p>nutrients&mdash;</p>"}],"keys":["1a23d05a-8e1a-4483-8ed1-77cd5d62bd22"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;nutrients&rdquo; pairs with the comma after &ldquo;photosynthesis&rdquo; to separate the supplementary element &ldquo;the mechanism by which plants use sunlight to turn carbon dioxide and water into nutrients&rdquo; from the rest of the sentence. This supplementary element functions to define the term &ldquo;photosynthesis,&rdquo; and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a conjunction can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a dash can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. </p>","parenttemplatename":"OSP-724-SEC","parenttemplateid":"","templateclusterid":"8182d867-dbdd-4c19-9cef-b91abef36e2b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$80aa7690$SATQ$, $SATQ$ad3374eb-4b0f-48b6-993c-634ad88d9e0b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The Austronesian language family includes Tagalog, Malagasy, and some 1,200 other languages throughout the Pacific, making it one of the largest language families in the world and of keen interest to <span aria-hidden="true">______</span><span class="sr-only">blank</span> of the University of Toronto.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7e09d577-f39f-46f3-865a-81ce7c962c37","content":"<p>linguist<span data-ssml-say-as=\"characters\">,</span> Diane Massam<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"25d5d59a-f520-427b-85cf-83dd3d58b488","content":"<p>linguist<span data-ssml-say-as=\"characters\">,</span> Diane Massam</p>"},{"id":"df57a294-2c8c-470f-b199-113670af44ec","content":"<p>linguist Diane Massam</p>"},{"id":"fc7e600f-8caa-48d7-8d40-c7f5a36a1d9d","content":"<p>linguist<span data-ssml-say-as=\"characters\">:</span> Diane Massam</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["df57a294-2c8c-470f-b199-113670af44ec"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to set off the proper noun "Diane Massam" from the title that describes Massam, "linguist." Because "Diane Massam" is essential information identifying the "linguist," no punctuation is necessary.</p><p>Choice A is incorrect because no punctuation is needed before or after the proper noun "Diane Massam." Setting the linguist&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"80aa7690","external_id":"ad3374eb-4b0f-48b6-993c-634ad88d9e0b","vaultid":null,"uId":"73adb57b-b4df-4887-8376-394eabe9efc5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The Austronesian language family includes Tagalog, Malagasy, and some 1,200 other languages throughout the Pacific, making it one of the largest language families in the world and of keen interest to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> of the University of Toronto.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7e09d577-f39f-46f3-865a-81ce7c962c37","content":"<p>linguist<span data-ssml-say-as=\"characters\">,</span> Diane Massam<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"25d5d59a-f520-427b-85cf-83dd3d58b488","content":"<p>linguist<span data-ssml-say-as=\"characters\">,</span> Diane Massam</p>"},{"id":"df57a294-2c8c-470f-b199-113670af44ec","content":"<p>linguist Diane Massam</p>"},{"id":"fc7e600f-8caa-48d7-8d40-c7f5a36a1d9d","content":"<p>linguist<span data-ssml-say-as=\"characters\">:</span> Diane Massam</p>"}],"keys":["df57a294-2c8c-470f-b199-113670af44ec"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to set off the proper noun \"Diane Massam\" from the title that describes Massam, \"linguist.\" Because \"Diane Massam\" is essential information identifying the \"linguist,\" no punctuation is necessary.</p><p>Choice A is incorrect because no punctuation is needed before or after the proper noun \"Diane Massam.\" Setting the linguist&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$819c443d$SATQ$, $SATQ$af698645-0a0d-4fae-bb26-4c38400997ff$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In January <span data-ssml-say-as="date">1776</span>, Thomas Paine published <em>Common Sense</em>, an appeal for freedom from the British monarchy that famously helped ignite the desire for independence among the American colonists. After the colonies achieved their independence, Paine moved to Paris, where the provocative <span aria-hidden="true">______</span><span class="sr-only">blank</span> would contribute to another revolution&mdash;the French Revolution.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"e2a3b9b2-500a-4a7b-8c5d-1ce8d7548462","content":"<p>authors political writings</p>"},{"id":"933d0365-8dc9-46a9-851e-9275ea6d20c6","content":"<p>author&rsquo;s political writings</p>"},{"id":"c5e710d0-e1eb-422e-a2f8-c4804764011d","content":"<p>author&rsquo;s political writing&rsquo;s</p>"},{"id":"ed461358-580f-402d-b941-a74b5d06c041","content":"<p>authors&rsquo; political writings&rsquo;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["933d0365-8dc9-46a9-851e-9275ea6d20c6"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The conventions being tested are the use of plural and possessive nouns. The singular possessive noun "author&rsquo;s" correctly indicates that the political writings are those of Thomas Paine, and the plural noun "writings" correctly indicates that multiple works by Paine are being discussed.</p><p>Choice A is incorrect because the context requires the singular possessive noun "author&rsquo;s," not the plural noun "authors." Choice C is incorrect because the context requires the plural noun "writings," not the singular possessive noun "writing&rsquo;s." Choice D is incorrect because the context requires the singular possessive noun "author&rsquo;s" and the plural noun "writings," not the plural possessive nouns "authors&rsquo;" and "writings&rsquo;."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"819c443d","external_id":"af698645-0a0d-4fae-bb26-4c38400997ff","vaultid":null,"uId":"2565cbb4-50a2-416f-b1cc-87a406d23eb8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In January <span data-ssml-say-as=\"date\">1776</span>, Thomas Paine published <em>Common Sense</em>, an appeal for freedom from the British monarchy that famously helped ignite the desire for independence among the American colonists. After the colonies achieved their independence, Paine moved to Paris, where the provocative <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> would contribute to another revolution&mdash;the French Revolution.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"e2a3b9b2-500a-4a7b-8c5d-1ce8d7548462","content":"<p>authors political writings</p>"},{"id":"933d0365-8dc9-46a9-851e-9275ea6d20c6","content":"<p>author&rsquo;s political writings</p>"},{"id":"c5e710d0-e1eb-422e-a2f8-c4804764011d","content":"<p>author&rsquo;s political writing&rsquo;s</p>"},{"id":"ed461358-580f-402d-b941-a74b5d06c041","content":"<p>authors&rsquo; political writings&rsquo;</p>"}],"keys":["933d0365-8dc9-46a9-851e-9275ea6d20c6"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The conventions being tested are the use of plural and possessive nouns. The singular possessive noun \"author&rsquo;s\" correctly indicates that the political writings are those of Thomas Paine, and the plural noun \"writings\" correctly indicates that multiple works by Paine are being discussed.</p><p>Choice A is incorrect because the context requires the singular possessive noun \"author&rsquo;s,\" not the plural noun \"authors.\" Choice C is incorrect because the context requires the plural noun \"writings,\" not the singular possessive noun \"writing&rsquo;s.\" Choice D is incorrect because the context requires the singular possessive noun \"author&rsquo;s\" and the plural noun \"writings,\" not the plural possessive nouns \"authors&rsquo;\" and \"writings&rsquo;.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$81ac953e$SATQ$, $SATQ$bb0a943d-ff9f-4fc0-84ad-b77c978840ff$SATQ$::uuid, $SATQ$3f2c8f15-bb46-4ab6-a79a-fdc008305be3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In 1899, Swedish chemist Svante Arrhenius developed an equation to answer a long-standing question: why do chemical reactions speed up at higher temperatures? The Arrhenius equation, named for its creator, <span aria-hidden="true">______</span><span class="sr-only">blank</span> an important concept in modern chemistry.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2090ece0-f093-4a99-97d4-3beff8143b07","content":"<p>have remained</p>"},{"id":"184cb706-82ef-4df7-b488-6c26fc9bb1a6","content":"<p>remain</p>"},{"id":"9884a20c-623f-42cb-9886-919b1a4b7b98","content":"<p>remains</p>"},{"id":"81800d2d-7ef4-4b27-8505-5b3b678f4b33","content":"<p>are remaining</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["9884a20c-623f-42cb-9886-919b1a4b7b98"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This choice uses the singular verb "remains" to match the singular subject "equation."</p><p>Choice A is incorrect. The singular noun "equation" doesn&rsquo;t match with the plural verb conjugation "have remained." Choice B is incorrect. The singular noun "equation" doesn&rsquo;t match with the plural verb conjugation "remain." Choice D is incorrect. The singular noun "equation" doesn&rsquo;t match with the plural verb conjugation "are remaining."</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-E010$SATQ$, $SATQ$$SATQ$, $SATQ$39216d7e-bf29-49d5-8a0a-3a5abcff4be6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"81ac953e","external_id":"bb0a943d-ff9f-4fc0-84ad-b77c978840ff","vaultid":"